  }
}

/* 保证移动端不受影响 */
#poem_sentence,
.poem-line {
  font-family: 'FZKai-Z03', 'FZShuSong-Z01', 'STKaiti', 'STXingkai', 'Hiragino Sans GB', '华文行楷', '华文楷体', '方正楷体', '方正行楷', '楷体', '行楷', 'SimKai', 'KaiTi', 'Microsoft YaHei', 'PingFang SC', '宋体', 'SimSun', serif;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 1.2px;
}

/* 可选：让诗句略有书法感 */
