}

[data-theme='dark'] .contact-details {
    background: rgba(102, 122, 242, 0.1);
    border: 1px solid rgba(102, 122, 242, 0.2);
}

[data-theme='dark'] .privacy-footer {
    background: rgba(25, 29, 35, 0.7);
}

[data-theme='dark'] .last-updated {
    background: rgba(102, 122, 242, 0.2);
}

[data-theme='dark'] .privacy-section {
    border-color: rgba(102, 122, 242, 0.4);
