        const startTime = Date.now();
        const checkInterval = 50; // 减少检查间隔到50毫秒，提高响应速度

        function check() {
            // 首先检查是否有全局标记表示数据库已加载
            if (window.CITY_SLOGANS_LOADED === true) {
                console.log('城市标语数据已加载完成（通过标记检测）');
