            // 检查是否超时
            if (Date.now() - startTime > maxWaitTime) {
                console.warn('等待城市标语数据加载超时，将使用默认数据');
                // 超时后尝试主动加载数据库
                ensureCitySloganData(true);
                callback();
                return;
            }

            // 继续等待
            setTimeout(check, checkInterval);
        }

        // 开始检查
        check();
    }

